<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>The Great Wave off Kanagawa — low poly 3D wallpaper</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #f0e6d2; }
  canvas { display: block; }
</style>
</head>
<body>
