<script type="module">
import * as THREE from 'three';

/*
 * Rebuild of Hokusai's "The Great Wave off Kanagawa" (c. 1831, public domain)
 * as a low poly 3D scene. The print is the reference, not a texture:
 *  - Composition: great breaking wave curling from the left, three fishing
 *    boats (funaya) riding the swells, snow-capped Mount Fuji small in the
 *    centre-right distance, clouds upper right.
 *  - Palette: Prussian blue, pale blue, cream paper, white foam, ochre hulls.
 *  - Gentle motion: swells undulate, foam puffs drift, boats bob and roll.
 */

// ---------- palette ----------
const C = {
  sky:     0xe8dcc4,
  blue:    0x1b3a6b,   // Prussian blue (wave body)
  blueMid: 0x2a5580,
  blueL:   0x4a7ba6,   // lighter blue (water base)
  foam:    0xf5f2e8,   // white foam
  hull:    0xc8a06a,   // ochre boat hull
  hullD:   0xa87f4a,
  fuji:    0x3a5a7a,   // Fuji body (blue-grey)
  snow:    0xf5f2e8,
  cloud:   0xf0e8d8,
};

